package com.pablo.controlgastos;
import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;import java.util.regex.*;
public class CreditCardsActivity extends Activity{
 CreditCardDb db;android.content.SharedPreferences p;LinearLayout body;TextView monthLabel;Button prev,next,change;int BG,TEXT,CARD,MUTED,cardIndex=0,statementIndex=-1;ArrayList<Card> cards=new ArrayList<>();ArrayList<Stmt> statements=new ArrayList<>();
 static class Card{long id;String name,last;Card(long i,String n,String l){id=i;name=n;last=l;}}static class Stmt{long id;String close,due,cur;double total;Stmt(long i,String c,String d,double t,String u){id=i;close=c;due=d;total=t;cur=u;}}static class SimRow{String desc,cur;int current,total;double amount;Switch sw;SimRow(String d,String c,int a,int t,double m){desc=d;cur=c;current=a;total=t;amount=m;}}
 public void onCreate(Bundle b){ThemePrefs.applyBaseTheme(this);super.onCreate(b);db=new CreditCardDb(this);p=getSharedPreferences(EmailSyncEngine.PREF,0);boolean l=ThemePrefs.isLight(this);BG=l?0xfff6f8f9:0xff0b1218;TEXT=l?0xff1f262c:0xfff2f5f7;CARD=l?Color.WHITE:0xff162029;MUTED=l?0xff5f6970:0xff9ea9b2;build();}
 int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}GradientDrawable cardBg(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));g.setStroke(dp(1),ThemePrefs.isLight(this)?0xffd7dde1:0xff263746);return g;}TextView t(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(TEXT);v.setPadding(dp(12),dp(10),dp(12),dp(10));return v;}Button btn(String s){Button x=new Button(this);x.setText(s);x.setAllCaps(false);x.setTextColor(TEXT);x.setTextSize(15);x.setBackground(cardBg(CARD,14));return x;}void margin(View v,int top,int bottom){ViewGroup.LayoutParams q=v.getLayoutParams();if(q instanceof LinearLayout.LayoutParams){LinearLayout.LayoutParams p=(LinearLayout.LayoutParams)q;p.setMargins(dp(4),dp(top),dp(4),dp(bottom));v.setLayoutParams(p);}}
 void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(14),dp(30),dp(14),dp(8));root.setBackgroundColor(BG);TextView head=t("Tarjetas de crédito",29);head.setTypeface(Typeface.DEFAULT,Typeface.BOLD);root.addView(head);LinearLayout top=new LinearLayout(this);top.setPadding(0,dp(2),0,dp(4));Button cfg=btn("✉  Correo\nConfigurar y leer"),sync=btn("↻  Leer\nElegir método");top.addView(cfg,new LinearLayout.LayoutParams(0,dp(62),1));top.addView(sync,new LinearLayout.LayoutParams(0,dp(58),1));root.addView(top);margin(cfg,0,0);margin(sync,0,0);cfg.setOnClickListener(v->startActivity(new Intent(this,EmailSettingsActivity.class)));sync.setOnClickListener(v->chooseReadSource());Button history=btn("▥   Historial, meses y simulación                                      ›");root.addView(history,new LinearLayout.LayoutParams(-1,dp(58)));margin(history,dp(4),dp(8));history.setOnClickListener(v->{if(!statements.isEmpty())renderSimulation();});change=btn("▣   Cambiar tarjeta                                                        ▾");root.addView(change,new LinearLayout.LayoutParams(-1,dp(58)));margin(change,dp(4),dp(8));change.setOnClickListener(v->chooseCard());LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER_VERTICAL);prev=btn("‹");monthLabel=t("",20);monthLabel.setGravity(Gravity.CENTER);monthLabel.setTypeface(Typeface.DEFAULT,Typeface.BOLD);next=btn("›");nav.addView(prev,new LinearLayout.LayoutParams(dp(60),dp(50)));nav.addView(monthLabel,new LinearLayout.LayoutParams(0,dp(50),1));nav.addView(next,new LinearLayout.LayoutParams(dp(64),dp(54)));root.addView(nav);prev.setOnClickListener(v->move(-1));next.setOnClickListener(v->move(1));ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(0,dp(4),0,dp(8));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);loadCards();}
 void chooseReadSource(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.HORIZONTAL);box.setPadding(dp(18),dp(8),dp(18),dp(8));Button mail=btn("✉\nCorreo\nLeer desde tu correo");Button shot=btn("▣\nCaptura de pantalla\nSeleccionar imagen");box.addView(mail,new LinearLayout.LayoutParams(0,dp(108),1));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,dp(108),1);sp.setMargins(dp(8),0,0,0);box.addView(shot,sp);AlertDialog dlg=new AlertDialog.Builder(this).setTitle("Leer estado de cuenta").setMessage("¿Desde dónde querés leerlo?").setView(box).setNegativeButton("Cancelar",null).create();mail.setOnClickListener(v->{dlg.dismiss();sync();});shot.setOnClickListener(v->{dlg.dismiss();startActivity(new Intent(this,CaptureStatementActivity.class));});dlg.show();}
 void loadCards(){cards.clear();Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,last4 FROM cards ORDER BY id",null);while(c.moveToNext())cards.add(new Card(c.getLong(0),c.getString(1),c.getString(2)));c.close();if(cards.isEmpty()){body.removeAllViews();body.addView(t("Todavía no hay tarjetas. Tocá ‘Leer’ para importar un estado desde el correo.",15));change.setText("Sin tarjetas");prev.setEnabled(false);next.setEnabled(false);return;}if(cardIndex>=cards.size())cardIndex=0;loadStatements(true);}
 void loadStatements(boolean latest){statements.clear();Card x=cards.get(cardIndex);Cursor c=db.getReadableDatabase().rawQuery("SELECT id,close_date,due_date,total,currency FROM statements WHERE card_id=? ORDER BY id",new String[]{""+x.id});while(c.moveToNext())statements.add(new Stmt(c.getLong(0),c.getString(1),c.getString(2),c.getDouble(3),c.getString(4)));c.close();if(latest)statementIndex=statements.size()-1;change.setText(x.name+" •••• "+x.last+"   ▾");render();}
 void chooseCard(){if(cards.isEmpty())return;String[] a=new String[cards.size()];for(int i=0;i<a.length;i++)a[i]=cards.get(i).name+" •••• "+cards.get(i).last;new AlertDialog.Builder(this).setTitle("Cambiar tarjeta").setSingleChoiceItems(a,cardIndex,(d,w)->{cardIndex=w;d.dismiss();loadStatements(true);}).setNegativeButton("Cancelar",null).show();}
 void move(int d){if(statements.isEmpty())return;if(d<0){if(statementIndex>0){statementIndex--;render();}}else{if(statementIndex<statements.size()-1){statementIndex++;render();}else renderSimulation();}}
 void render(){body.removeAllViews();Card card=cards.get(cardIndex);if(statements.isEmpty()){monthLabel.setText("Sin estados");body.addView(t("No hay estados importados para esta tarjeta.",15));prev.setEnabled(false);next.setEnabled(false);return;}Stmt s=statements.get(statementIndex);monthLabel.setText(monthName(s.close));prev.setEnabled(statementIndex>0);next.setEnabled(true);TextView sum=t("Cierre: "+s.close+"   ·   Vence: "+s.due+"\nPago contado: "+s.cur+" "+String.format(Locale.US,"%.2f",s.total)+payment(s.total,s.cur,s.due,card.last),17);sum.setBackground(cardBg(CARD,16));LinearLayout.LayoutParams slp=new LinearLayout.LayoutParams(-1,-2);slp.setMargins(0,dp(4),0,dp(8));body.addView(sum,slp);body.addView(t("Compras y cuotas",18));Cursor c=db.getReadableDatabase().rawQuery("SELECT tx_date,description,installment,amount,currency FROM installments WHERE statement_id=? ORDER BY id",new String[]{""+s.id});while(c.moveToNext()){String inst=installmentInfo(c.getString(2));TextView v=t(c.getString(1)+"\n"+(inst.isEmpty()?"Compra sin cuota detectada":inst)+"\nMonto: "+c.getString(4)+" "+String.format(Locale.US,"%.2f",c.getDouble(3))+"   ·   "+c.getString(0),15);v.setBackground(cardBg(CARD,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(3),0,dp(3));body.addView(v,lp);}c.close();if(statementIndex==statements.size()-1){Button sim=btn("Ver mes siguiente simulado");body.addView(sim);sim.setOnClickListener(v->renderSimulation());}}
 String monthName(String close){if(close==null)return"Estado";String raw=close.trim();String pattern=raw.matches(".*\\d{4}$")?"dd/MM/yyyy":"dd/MM/yy";try{SimpleDateFormat in=new SimpleDateFormat(pattern,Locale.US);in.setLenient(false);Date d=in.parse(raw);String s=new SimpleDateFormat("MMMM yyyy",new Locale("es","UY")).format(d);return s.substring(0,1).toUpperCase()+s.substring(1);}catch(Exception ignored){return raw;}}
 void renderSimulation(){if(statements.isEmpty())return;Stmt s=statements.get(statements.size()-1);Card card=cards.get(cardIndex);ArrayList<SimRow> rows=new ArrayList<>();Cursor c=db.getReadableDatabase().rawQuery("SELECT description,installment,amount,currency FROM installments WHERE statement_id=? ORDER BY id",new String[]{""+s.id});while(c.moveToNext()){int[] q=installmentNumbers(c.getString(1));if(q!=null)rows.add(new SimRow(c.getString(0),c.getString(3),q[0],q[1],c.getDouble(2)));}c.close();body.removeAllViews();monthLabel.setText("Mes siguiente · simulado");prev.setEnabled(true);next.setEnabled(false);TextView total=t("",20);body.addView(total);TextView note=t("Proyección basada solo en las cuotas conocidas del último estado. Las cuotas que terminan este mes se quitan automáticamente. No incluye compras nuevas, cargos, intereses ni ajustes futuros.",13);note.setTextColor(MUTED);body.addView(note);Button restore=btn("↺ Restaurar escenario");body.addView(restore);for(SimRow r:rows){boolean cont=r.current<r.total;Switch sw=new Switch(this);r.sw=sw;sw.setChecked(cont);sw.setEnabled(cont);sw.setText(r.desc+"\n"+(cont?("Próximo: cuota "+(r.current+1)+" de "+r.total):"Finaliza este mes")+"\n"+r.cur+" "+String.format(Locale.US,"%.2f",r.amount));sw.setTextColor(TEXT);sw.setPadding(10,12,10,12);body.addView(sw);sw.setOnCheckedChangeListener((b,on)->updateSimulation(rows,total));}restore.setOnClickListener(v->{for(SimRow r:rows)if(r.current<r.total)r.sw.setChecked(true);updateSimulation(rows,total);});updateSimulation(rows,total);Button back=btn("‹ Volver al último estado");body.addView(back);back.setOnClickListener(v->{statementIndex=statements.size()-1;render();});}
 void updateSimulation(ArrayList<SimRow> rows,TextView v){LinkedHashMap<String,Double>sums=new LinkedHashMap<>();int active=0,end=0,excluded=0;for(SimRow r:rows){if(r.current>=r.total){end++;continue;}if(r.sw!=null&&r.sw.isChecked()){sums.put(r.cur,sums.containsKey(r.cur)?sums.get(r.cur)+r.amount:r.amount);active++;}else excluded++;}StringBuilder b=new StringBuilder("Próximo estado estimado");if(sums.isEmpty())b.append("\n$ 0,00");else for(Map.Entry<String,Double>e:sums.entrySet())b.append("\n").append(e.getKey()).append(" ").append(String.format(Locale.US,"%.2f",e.getValue()));b.append("\n\nContinúan: ").append(active).append(" · terminan: ").append(end).append(" · excluidas: ").append(excluded);v.setText(b.toString());}
 int[] installmentNumbers(String raw){if(raw==null)return null;Matcher m=Pattern.compile("(?i)CUOTA\\s*0*(\\d{1,2})/0*(\\d{1,2})").matcher(raw);if(!m.find())return null;try{return new int[]{Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2))};}catch(Exception e){return null;}}String installmentInfo(String raw){int[]q=installmentNumbers(raw);if(q==null)return raw==null?"":raw;int left=Math.max(0,q[1]-q[0]);return"Cuota "+q[0]+" de "+q[1]+" · "+left+" restante"+(left==1?"":"s");}
 String payment(double total,String cur,String due,String last4){boolean am=p.getBoolean("card_cmp_amount",true),tx=p.getBoolean("card_cmp_text",true),cu=p.getBoolean("card_cmp_currency",true),date=p.getBoolean("card_cmp_due_date",false),last=p.getBoolean("card_cmp_last4",false);if(!am&&!tx&&!cu&&!date&&!last)return"\nIdentificación de pago desactivada";ExpenseDb e=new ExpenseDb(this);Cursor c=e.getReadableDatabase().rawQuery("SELECT amount,description,currency,COALESCE(original_ts,ts),original_text FROM tx WHERE type='GASTO' ORDER BY ts DESC LIMIT 500",null);try{long dueTs=parseDue(due);while(c.moveToNext()){String d=(c.getString(1)==null?"":c.getString(1))+" "+(c.getString(4)==null?"":c.getString(4));String up=d.toUpperCase(Locale.ROOT);if(am&&Math.abs(c.getDouble(0)-total)>.01)continue;if(tx&&!(up.contains("PAGO TC")||up.contains("PAGO DE TARJETA")))continue;if(cu&&!cur.equalsIgnoreCase(c.getString(2)))continue;if(date&&dueTs>0&&Math.abs(c.getLong(3)-dueTs)>15L*24*3600*1000)continue;if(last&&!d.contains(last4))continue;return"\n✓ Pago de tarjeta identificado";}return"\nPago aún no identificado";}finally{c.close();e.close();}}
 long parseDue(String s){if(s==null)return 0;String raw=s.trim();String pattern=raw.matches(".*\\d{4}$")?"dd/MM/yyyy":"dd/MM/yy";try{SimpleDateFormat d=new SimpleDateFormat(pattern,Locale.US);d.setLenient(false);return d.parse(raw).getTime();}catch(Exception ignored){return 0;}}
 void help(){new AlertDialog.Builder(this).setTitle("Ayuda · Tarjetas").setMessage("Usá ‘Cambiar tarjeta’ para alternar entre tarjetas. Las flechas ‹ y › recorren los estados mensuales importados. Desde el último estado, › abre el mes siguiente simulado.\n\nLa simulación elimina automáticamente las cuotas que están en su última entrega y avanza las restantes (por ejemplo 5/6 → 6/6). Podés desactivar cuotas para probar escenarios.\n\nLa proyección no puede anticipar compras nuevas, intereses, seguros, impuestos ni otros cargos que todavía no aparecieron.").setPositiveButton("Entendido",null).show();}
 void sync(){ProgressDialog d=ProgressDialog.show(this,"Tarjetas","Leyendo estados nuevos…",true,false);new Thread(()->{try{EmailSyncEngine.Result r=EmailSyncEngine.readCards(this,false);runOnUiThread(()->{d.dismiss();loadCards();Toast.makeText(this,"Estados actualizados: "+r.imported,Toast.LENGTH_LONG).show();});}catch(Exception ex){runOnUiThread(()->{d.dismiss();new AlertDialog.Builder(this).setTitle("No se pudo leer el correo").setMessage(ex.getMessage()+"\n\nRevisá Ajustes → Correo y lecturas.").setPositiveButton("Aceptar",null).show();});}}).start();}
}
